import {readFileSync,writeFileSync} from 'node:fs';
import {compileDecisionScripts} from '@wildshard/sharddev/buildDecisionScripts';
import {compileReturnProjectionV2} from '@wildshard/sharddev/returnProjectionV2';
import {nalatiSpeciesProgram} from '<checkouts>/shard-nalati/src/generators/speciesProgram.ts';
import {CreatureGuestSchema} from '@wildshard/format/speciesBookRows';
import {parse} from 'valibot';
const source='<checkouts>/shard-nalati';
const files=await nalatiSpeciesProgram({compileDecisionRows:compileDecisionScripts,compileReturnProjection:compileReturnProjectionV2,cached:(step,make)=>Promise.resolve(make(new Map(step.inputs.map(name=>[name,new Uint8Array(readFileSync(source+(name.startsWith('/')?'/public'+name:'/src/'+name)))]))))},input=>input,input=>parse(CreatureGuestSchema,input),hash=>`/assets/nalati/baked/bodies-${hash}.bin`);
