const {bakeSheepBody}=await import(source+'/src/generators/sheepBody.ts');
const {bytes,...metadata}=bakeSheepBody();
writeFileSync('tmp/codex-tc48/sheep.bin',bytes);writeFileSync('tmp/codex-tc48/sheep.json',JSON.stringify(metadata));
